class Solution:
    def numMatchingSubseq(self, s: str, words: list[str]) -> int:
        import collections
        waiting = collections.defaultdict(list)
        for word in words:
            waiting[word[0]].append(iter(word[1:]))
        count = 0
        for c in s:
            advancing = waiting[c]
            waiting[c] = []
            for it in advancing:
                nxt = next(it, None)
                if nxt is None:
                    count += 1
                else:
                    waiting[nxt].append(it)
        return count

